def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    seen=set()
    comps=[]
    for r in range(h):
        for c in range(w):
            color=g[r][c]
            if color in (0,1) or (r,c) in seen: continue
            stack=[(r,c)]; seen.add((r,c)); cells=[]
            while stack:
                y,x=stack.pop(); cells.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    p=(y+dy,x+dx)
                    if 0<=p[0]<h and 0<=p[1]<w and p not in seen and g[p[0]][p[1]]==color:
                        seen.add(p); stack.append(p)
            comps.append((color,cells))
    ones=[]; seen=set()
    for r in range(h):
        for c in range(w):
            if g[r][c]!=1 or (r,c) in seen: continue
            stack=[(r,c)];seen.add((r,c));cells=[]
            while stack:
                y,x=stack.pop();cells.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    p=(y+dy,x+dx)
                    if 0<=p[0]<h and 0<=p[1]<w and p not in seen and g[p[0]][p[1]]==1:
                        seen.add(p);stack.append(p)
            ones.append(cells)
    def shape(cells):
        a=min(r for r,c in cells); b=min(c for r,c in cells)
        return frozenset((r-a,c-b) for r,c in cells)
    for color,cells in comps:
        sh=shape(cells)
        for one in ones:
            if shape(one)==sh:
                for r,c in one: g[r][c]=color
                break
    return g
